completion:
form "Conference Registration" {
  field full_name: text ui { label: "Full name" } validate { required }
  field email: email ui { label: "Email address" } validate { required }
  field dietary_preferences: checkbox {
    option "Vegetarian"
    option "Vegan"
    option "Gluten-free"
    option "No restrictions"
  }
  ui { label: "Dietary preferences" }
}

form "Reading Log" {
  field book_count: integer ui { label: "Number of books read" } validate { required min: 1 max: 20 }
  repeat count = book_count {
    field book_name: text ui { label: "Book name" } validate { required }
    field release_date: date ui { label: "Release date" }
    field author: text ui { label: "Author" } validate { required }
  }
}

form "Participant Details" {
  field age: integer ui { label: "Age" } validate { required min: 0 max: 120 }
  if age >= 18 {
    field occupation: text ui { label: "Occupation" }
  } else {
    field guardian_name: text ui { label: "Guardian name" } validate { required }
  }
}

form "Profile Wizard" {
  page "Contact" {
    field full_name: text ui { label: "Full name" } validate { required }
    field email: email ui { label: "Email address" } validate { required }
  }
  page "Preferences" {
    field website: url ui { label: "Website" }
    field contact_method: radio { option "Email" option "Phone" } ui { label: "Preferred contact method" }
  }
}

form "Job Application" {
  field full_name: text ui { label: "Full name" } validate { required }
  field email: email ui { label: "Email address" } validate { required }
  field resume: upload { accept: pdf,document required maxSize: "10MB" } ui { label: "Resume" }
}

form "Order Calculator" {
  field quantity: integer ui { label: "Quantity" } validate { required min: 1 max: 100 }
  field unit_price: float ui { label: "Unit price" } validate { required min: 0 }
  field total: float compute = quantity * unit_price
}

form "Department Selection" {
  field department: select from url "https://example.invalid/departments" map {
    label: name,
    value: id
  }
}

